	explicit binary_stream_writer(buffer_write& source, no_throw_t)
		: stream_base(source, false),
		  buffer_(source),
		  total_write_(0) {}

	binary_stream_writer(binary_stream_writer&& rhs) noexcept
		: stream_base(rhs),
