struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    // Create mutable span for buffer_adaptor (reading operations won't modify data)
    auto mutable_buffer = std::span<uint8_t>(
        const_cast<uint8_t*>(buffer.data()), 
        buffer.size()
    );

    hexi::buffer_adaptor adaptor(mutable_buffer);
    hexi::binary_stream stream(adaptor);

    NetworkPacket packet;

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using the length prefix
    stream >> packet.username;

    // Read the score count, then use read_container to read the scores vector
    stream >> hexi::prefixed(packet.scores);

    // Read the metadata string as null-terminated
    stream >> hexi::null_terminated(packet.metadata);

    // Skip any remaining padding bytes (if any)
    if (stream.size() > 0) {
        stream.skip(stream.size());
    }

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    // Create mutable span for buffer_adaptor
    auto mutable_buffer = std::span<uint8_t>(
        const_cast<uint8_t*>(buffer.data()), 
        buffer.size()
    );

    hexi::buffer_adaptor adaptor(mutable_buffer);
    hexi::binary_stream stream(adaptor);

    PacketInfo info;

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto packet_id_span = stream.span<uint32_t>(1);
    info.packet_id = packet_id_span[0];

    // Read username using prefixed adaptor to get a string_view
    std::string_view username_view;
    stream >> username_view;
    info.username = username_view;

    // Skip the scores vector without reading its elements (read count, then skip the data)
    uint32_t score_count = 0;
    stream >> hexi::endian::le(score_count);
    stream.skip(score_count * sizeof(uint32_t));

    return info;
}
