struct PacketHeader {
    uint8_t version;
    uint8_t flags;
    uint16_t packet_id;
};

PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // Create a mutable span for the buffer adaptor (safe for read-only operations)
    auto mutable_buffer = std::span<uint8_t>(
        const_cast<uint8_t*>(buffer.data()), 
        buffer.size()
    );

    // Create buffer adaptor and binary stream
    hexi::buffer_adaptor adaptor(mutable_buffer);
    hexi::binary_stream stream(adaptor);

    // Use span() to get zero-copy view of header (1 PacketHeader element)
    auto header_span = stream.span<PacketHeader>(1);

    // Return the header from the span
    return header_span[0];
}

std::string_view read_message_until_delimiter(const std::span<const uint8_t> buffer) {
    // Create a mutable span for the buffer adaptor (safe for read-only operations)
    auto mutable_buffer = std::span<uint8_t>(
        const_cast<uint8_t*>(buffer.data()), 
        buffer.size()
    );

    // Create buffer adaptor and binary stream
    hexi::buffer_adaptor adaptor(mutable_buffer);
    hexi::binary_stream stream(adaptor);

    // Use view() to read null-terminated string with zero-copy
    return stream.view();
}
