    std::cout << "- Free list operates in LIFO (Last In, First Out) manner" << std::endl;
    std::cout << "- allocate() internally calls pop() to get a free block" << std::endl;
    std::cout << "- deallocate() internally calls push() to return blocks to free list" << std::endl;
    std::cout << "- If free list is empty (pop() returns nullptr), new is used" << std::endl;
