	* @brief Explicitly close the underlying file handle.
	* 
	* This function will be called by the object's destructor
	* and does not need to be called explicitly.
	* 
	* @note Idempotent.
	*/
	void close() {
		if(file_) {
			std::fclose(file_);
			file_ = nullptr;
		}
	}

