		  write_(rhs.write_),
		  error_(rhs.error_) {
		rhs.file_ = nullptr;
	}

	file_buffer& operator=(file_buffer&& rhs) noexcept {
		std::exchange(file_, rhs.file_);
		read_ = rhs.read_;
		write_ = rhs.write_;
		error_ = rhs.error_;
		return *this;
	}

