	void copy(void* destination, size_type length) {
		if(error_) {
			return;
		} else if(length > size()) {
			error_ = true;
			HEXI_THROW(buffer_underrun(length, read_, size()));
		}

		if(std::fseek(file_, read_, SEEK_SET)) {
			error_ = true;
			return;
		}

		if(std::fread(destination, length, 1, file_) != 1) {
			error_ = true;
			return;
		}
	}

