	/**
	 * @return Pointer to the data available for reading.
	 */
	auto read_ptr() const {
		return buffer_.data() + read_;
	}

	/**
	 * @return Pointer to the data available for reading.
	 */
	auto read_ptr() {
		return buffer_.data() + read_;
	}

	/**
	 * @return Pointer to the location within the buffer where the next write
